from collections import defaultdict

def is_rotationally_symmetrical(n, m, segments):
    # Create a graph representation of the segments
    graph = defaultdict(list)
    for a, b in segments:
        graph[a].append(b)
        graph[b].append(a)

    # Check if there exists a valid rotation
    def check_rotation(k):
        visited = set()
        for start in range(1, n+1):
            if start not in visited:
                stack = [(start, k)]
                while stack:
                    current, shift = stack.pop()
                    if current in visited:
                        return False
                    visited.add(current)
                    next_point = (current - shift) % n
                    if next_point == 0:
                        next_point = n
                    if next_point != current and next_point not in graph[current]:
                        return False
                    for neighbor in graph[next_point]:
                        if neighbor not in visited:
                            stack.append((neighbor, (shift - (next_point - neighbor)) % n))
        return True

    for k in range(1, n):
        if check_rotation(k):
            return "Yes"
    return "No"

