        return ((a - 1 + k) % n + 1, (b - 1 + k) % n + 1)

    sorted_edges = sorted(edges)
    for k in range(1, n):
        rotated_edges = [rotate_segment(a, b, k) for a, b in sorted_edges]
        if sorted_edges == sorted(rotated_edges):
