def is_rotationally_symmetrical(n, m, segments):
    def get_relative_position(a, b):
        return (b - a) % n

    positions = {}
    for a, b in segments:
        pos_a = get_relative_position(1, a)
        pos_b = get_relative_position(1, b)
        if pos_a > pos_b:
            pos_a, pos_b = pos_b, pos_a
        if (pos_a, pos_b) not in positions:
            positions[(pos_a, pos_b)] = 1
        else:
            positions[(pos_a, pos_b)] += 1

    for key, value in positions.items():
        if value % n != 0:
            return "No"
    return "Yes"

