from collections import defaultdict

def is_rotationally_symmetric(n, m, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, parent, color_map, current_color):
        color_map[node] = current_color
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if neighbor in color_map:
                if color_map[neighbor] != current_color:
                    return False
            else:
                if not dfs(neighbor, node, color_map, 1 - current_color):
                    return False
        return True

    color_map = {}
    components = []
    for node in range(1, n + 1):
        if node not in color_map:
            components.append(dfs(node, -1, color_map, 0))

    if not all(component for component in components):
        return "No"

    def check_symmetry():
        for i in range(1, n // 2 + 1):
            for j in range(1, n + 1):
                if (j + i > n):
                    target = j + i - n
                else:
                    target = j + i
                if (j, target) not in edges and (target, j) not in edges:
                    return False
        return True

    return "Yes" if check_symmetry() else "No"

